#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Production setup for Calories Counter (docs/specs/001-environments-and-deploy.md).
# Run from the repo root: ./scripts/setup-production.sh
# Needs: gh (logged in), Node 24 + pnpm. Safe to re-run: public values are remembered,
# secrets are never written to disk (only to GitHub), so you paste those again.

ENV_FILE=".env.production.local"   # gitignored; holds public identifiers only
VERCEL_CLI="vercel@65.0.0"         # keep in step with .github/workflows/deploy.yml
SUPABASE_REF_DEFAULT="xrfbpeiugmacbossropu"   # calories-counter, ap-southeast-2 (Sydney)
VERCEL_PROJECT_NAME="calories-counter"

TOTAL_STAGES=6

if ! command -v gh >/dev/null 2>&1 || ! gh auth status >/dev/null 2>&1; then
  printf '\n  gh (GitHub CLI) must be installed and logged in first: gh auth login\n\n'
  exit 1
fi

banner "Calories Counter: production setup"

# ── 1. Supabase: project identity and public API values ────────────────────
stage "Supabase: project and public keys"
say "Production uses the Sydney project. Its reference is $SUPABASE_REF_DEFAULT."
SUPABASE_PROJECT_REF=$(_existing SUPABASE_PROJECT_REF || true)
SUPABASE_PROJECT_REF="${SUPABASE_PROJECT_REF:-$SUPABASE_REF_DEFAULT}"
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/settings/api-keys"
step "On the API Keys page, copy the Publishable key (starts sb_publishable_)."
ask NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY "Paste the publishable key:"
NEXT_PUBLIC_SUPABASE_URL="https://${SUPABASE_PROJECT_REF}.supabase.co"
write_env SUPABASE_PROJECT_REF "$SUPABASE_PROJECT_REF"
write_env NEXT_PUBLIC_SUPABASE_URL "$NEXT_PUBLIC_SUPABASE_URL"
write_env NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY "$NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY"
set_secret SUPABASE_PROJECT_REF "$SUPABASE_PROJECT_REF"

# ── 2. Supabase: credentials the deploy workflow uses to push migrations ───
stage "Supabase: access token and database password"
say "The Deploy workflow links the project and applies migrations with these."
open_url "https://supabase.com/dashboard/account/tokens"
step "Click 'Generate new token', name it 'calories-counter-deploy', and copy it."
ask_secret SUPABASE_ACCESS_TOKEN "Paste the access token:"
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/database/settings"
step "Under 'Database password', use your project password, or click 'Reset database password'."
note "Nothing uses the password yet, so resetting it is safe. Avoid '@', ':' and '/' in a new one."
ask_secret SUPABASE_DB_PASSWORD "Paste the database password:"
set_secret SUPABASE_ACCESS_TOKEN "$SUPABASE_ACCESS_TOKEN"
set_secret SUPABASE_DB_PASSWORD "$SUPABASE_DB_PASSWORD"

# ── 3. Vercel: token and project ───────────────────────────────────────────
stage "Vercel: token and project"
say "Vercel only hosts the app; deploys come from GitHub Actions (vercel.json turns Git deploys off)."
open_url "https://vercel.com/account/tokens"
step "Create a token named 'calories-counter-deploy' (expiry: your choice) and copy it."
ask_secret VERCEL_TOKEN "Paste the Vercel token:"
set_secret VERCEL_TOKEN "$VERCEL_TOKEN"
open_url "https://vercel.com/new"
step "Import the GitHub repo streetlampsalad/calories-counter. Keep the Next.js preset and defaults."
step "Name the project '$VERCEL_PROJECT_NAME'. Do NOT add environment variables here (the next stages do)."
note "The first build may fail or be skipped; that is fine. All later deploys come from GitHub Actions."
pause "Press Enter once the project exists in Vercel"

# ── 4. Vercel: org and project IDs ─────────────────────────────────────────
stage "Vercel: project and team IDs"
say "Linking this folder to the Vercel project so the wizard can read its IDs."
VERCEL_ORG_ID=""
VERCEL_PROJECT_ID=""
if pnpm dlx "$VERCEL_CLI" link --yes --project "$VERCEL_PROJECT_NAME" --token "$VERCEL_TOKEN"; then
  if [[ -f .vercel/project.json ]]; then
    VERCEL_ORG_ID=$(node -pe 'JSON.parse(require("fs").readFileSync(".vercel/project.json","utf8")).orgId')
    VERCEL_PROJECT_ID=$(node -pe 'JSON.parse(require("fs").readFileSync(".vercel/project.json","utf8")).projectId')
  fi
fi
if [[ -z "$VERCEL_ORG_ID" || -z "$VERCEL_PROJECT_ID" ]]; then
  warn "Couldn't read the IDs automatically; copy them from the dashboard instead."
  open_url "https://vercel.com/dashboard"
  step "Open the project → Settings → General, and copy 'Project ID' (starts prj_)."
  ask VERCEL_PROJECT_ID "Paste the Project ID:"
  step "Open your team (or account) Settings → General, and copy the 'ID' / 'Team ID'."
  ask VERCEL_ORG_ID "Paste the Team/Account ID:"
fi
write_env VERCEL_ORG_ID "$VERCEL_ORG_ID"
write_env VERCEL_PROJECT_ID "$VERCEL_PROJECT_ID"
set_secret VERCEL_ORG_ID "$VERCEL_ORG_ID"
set_secret VERCEL_PROJECT_ID "$VERCEL_PROJECT_ID"

# ── 5. Vercel: production environment variables ────────────────────────────
stage "Vercel: production environment variables"
say "The app reads these at runtime (src/lib/env.ts fails fast if they are missing)."
add_vercel_env() {
  local name="$1" value="$2"
  if printf '%s' "$value" | pnpm dlx "$VERCEL_CLI" env add "$name" production --token "$VERCEL_TOKEN" >/dev/null 2>&1; then
    printf '  %s✓ added%s %s to Vercel production\n' "$GREEN" "$RESET" "$name"
  else
    SKIPPED+=("Vercel env $name (add it in Project → Settings → Environment Variables, Production)")
    warn "couldn't add $name (it may already exist); check Project → Settings → Environment Variables"
  fi
}
add_vercel_env NEXT_PUBLIC_SUPABASE_URL "$NEXT_PUBLIC_SUPABASE_URL"
add_vercel_env NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY "$NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY"

# ── 6. Production URL and a final check ────────────────────────────────────
stage "Production URL and check"
say "The Deploy workflow polls <production URL>/api/health to confirm each release."
open_url "https://vercel.com/dashboard"
step "Open the project → Settings → Domains. Copy the production domain (e.g. https://calories-counter.vercel.app)."
ask PRODUCTION_URL "Paste the production URL:"
PRODUCTION_URL="${PRODUCTION_URL%/}"
[[ "$PRODUCTION_URL" == https://* ]] || PRODUCTION_URL="https://${PRODUCTION_URL}"
write_env PRODUCTION_URL "$PRODUCTION_URL"
set_var PRODUCTION_URL "$PRODUCTION_URL"
say ""
say "Checking that every secret the Deploy workflow reads is set on GitHub:"
missing=0
secrets_present=$(gh secret list 2>/dev/null | cut -f1 || true)
for name in SUPABASE_ACCESS_TOKEN SUPABASE_DB_PASSWORD SUPABASE_PROJECT_REF VERCEL_TOKEN VERCEL_ORG_ID VERCEL_PROJECT_ID; do
  if grep -qx "$name" <<<"$secrets_present"; then
    printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$name"
  else
    printf '  %s✗%s %s\n' "$RED" "$RESET" "$name"
    missing=1
  fi
done
if (( missing )); then
  SKIPPED+=("Re-run this wizard: not all GitHub secrets are set")
else
  note "All set. To deploy: push any commit to main (or re-run the Deploy workflow)."
fi

finish
